 memAddComment(m);mem.RLock();out:=mem.comment(m.ID);mem.RUnlock();return c.JSON(201,out)
}
func fastEnter(c echo.Context)error{
 if err:=verifyUserSession(c);err!=nil{return err};lid,err:=memID(c);if err!=nil{return err};uid:=memUID(c);unlock:=lockStream(lid+1000000000000);defer unlock()
 _,err=dbConn.ExecContext(c.Request().Context(),"INSERT INTO livestream_viewers_history(user_id,livestream_id,created_at) VALUES(?,?,?)",uid,lid,time.Now().Unix());if err!=nil{return err};memEnter(uid,lid);return c.NoContent(http.StatusOK)
