 if err:=verifyUserSession(c);err!=nil{return err};lid,err:=memID(c);if err!=nil{return err};uid:=memUID(c);unlock:=lockStream(lid+1000000000000);defer unlock()
 _,err=dbConn.ExecContext(c.Request().Context(),"DELETE FROM livestream_viewers_history WHERE user_id=? AND livestream_id=?",uid,lid);if err!=nil{return err};memExit(uid,lid);return c.NoContent(http.StatusOK)
}
