 var req PostIconRequest;if err:=json.NewDecoder(c.Request().Body).Decode(&req);err!=nil{return echo.NewHTTPError(400,"invalid json")}
 unlock:=lockStream(-uid);defer unlock()
 r,err:=dbConn.ExecContext(c.Request().Context(),"INSERT INTO icons(user_id,image) VALUES(?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(VALUES(id)),image=VALUES(image)",uid,req.Image);if err!=nil{return err};id,err:=r.LastInsertId();if err!=nil{return err};memIcon(uid,req.Image);return c.JSON(201,PostIconResponse{ID:id})
}
func fastPostReport(c echo.Context)error{
 if err:=verifyUserSession(c);err!=nil{return err};lid,err:=memID(c);if err!=nil{return err};uid:=memUID(c);cid,err:=strconv.ParseInt(c.Param("livecomment_id"),10,64);if err!=nil{return echo.NewHTTPError(400,"invalid livecomment id")}
 unlock:=lockStream(lid);defer unlock()
 mem.RLock();_,exists:=mem.streams[lid];_,commentExists:=mem.comments[cid];active:=false;for _,id:=range mem.commentIDs[lid]{if id==cid{active=true;break}};mem.RUnlock()
 if !exists||!commentExists||!active{return echo.NewHTTPError(404,"livecomment not found")}
 m:=LivecommentReportModel{UserID:uid,LivestreamID:lid,LivecommentID:cid,CreatedAt:time.Now().Unix()}
